{{ config(
    tags=['m_MT_RSTD_SA_BKGS_MONTH']
) }}
{{ config(materialized='table') }}
-- Self-referencing table(s): 'MT_RSTD_SA_BKGS_MONTH_PRODUCT' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
   BKG_CHNL_MSR.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
   BKG_CHNL_MSR.PARTNER_SITE_PARTY_KEY AS PARTNER_SITE_PARTY_KEY,
   CASE
      WHEN BKG_CHNL_MSR.CHANNEL_BOOKINGS_FLG IS NULL
         THEN 'N'
      ELSE BKG_CHNL_MSR.CHANNEL_BOOKINGS_FLG
   END CHANNEL_BOOKINGS_FLG,
   'OTHER' AS BK_PRODUCT_SUBGROUP_ID,
   BKGS.PRODUCT_KEY,
   BKGS.SALES_TERRITORY_KEY,
   BKGS.SALES_REP_NUMBER SALES_REP_NUM,
   FD2Y.FISCAL_YEAR_MONTH_INT AS FISCAL_YEAR_MTH_NUM_INT,
   BKGS.END_CUSTOMER_KEY,
   BKGS.BILL_TO_CUSTOMER_KEY,
   BKGS.SHIP_TO_CUSTOMER_KEY,
   BKGS.SOLD_TO_CUSTOMER_KEY,
   BKGS.BKGS_MEASURE_TRANS_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CD,
   BKGS.SERVICE_FLG,
   SUM(BKGS.DD_EXTENDED_QUANTITY) AS EXTENDED_QTY,
   SUM(BKGS.DD_EXTENDED_HOLD_QUANTITY) AS EXTENDED_HOLD_QTY,
   BKGS.WIPS_ORIGINATOR_ID_INT,
   SUM(DD_COMP_US_NET_PRICE_AMOUNT) AS COMP_US_NET_PRICE_AMT,
   SUM(DD_COMP_US_LIST_PRICE_AMOUNT) AS COMP_US_LIST_PRICE_AMT,
   SUM(DD_COMP_US_COST_AMOUNT) AS COMP_US_COST_AMT,
   SUM(DD_COMP_US_HOLD_NET_PRICE_AMT) AS COMP_US_HOLD_NET_PRICE_AMT,
   SUM(DD_COMP_US_HOLD_LIST_PRICE_AMT) AS COMP_US_HOLD_LIST_PRICE_AMT,
   SUM(DD_COMP_US_HOLD_COST_AMOUNT) AS COMP_US_HOLD_COST_AMOUNT,
   SUM(DD_COMP_US_STANDARD_PRICE_AMT) AS COMP_US_STANDARD_PRICE_AMT,
   BKGS.CORPORATE_BOOKINGS_FLG,
   SUM(BKGS.TRADE_IN_AMOUNT) AS TRADE_IN_AMT,
   SUM(DV_ANNUALIZED_US_NET_AMT) AS DV_ANNUALIZED_US_NET_AMT,
   SUM(DV_MULTIYEAR_US_NET_AMT) AS DV_MULTIYEAR_US_NET_AMT,
   BKGS.DV_REVENUE_RECOGNITION_FLG,
   BKGS.DV_NET_SPREAD_FLG,
   BKGS.DV_ATTRIBUTION_CD,
   DV_PRODUCT_KEY,
   BKGS.DV_FMV_FLG,
   'OTHER' BK_SERVICE_CATEGORY_ID,
   CANCEL_CODE AS CANCEL_CD,
   BKGS.ADJUSTMENT_CODE AS BK_SALES_ADJ_CD,
   BKGS.DSV_FLG /* Added as part of  Q1FY16 DSV **/,
   /* Added the below columns as part of  RO project  Q3FY17**/
   BKGS.XCAT_FLG,
   BKGS.BK_OFFER_TYPE_NAME,
   BKGS.RECURRING_OFFER_FLG,
   BKGS.ELA_FLG,
   BKGS.DV_RECURRING_OFFER_CD
FROM
   {{ var('m_MT_RSTD_SA_BKGS_MONTH_SLSORDVWDB') }}.MT_RSTD_BKGS_MEASURE BKGS
   INNER JOIN
      {{ var('m_MT_RSTD_SA_BKGS_MONTH_SLSORDVWDB') }}.N_BKGS_CHNL_MEASURE BKG_CHNL_MSR
      ON BKGS.BOOKINGS_MEASURE_KEY = BKG_CHNL_MSR.BOOKINGS_MEASURE_KEY
      AND BKGS.BOOKINGS_PROCESS_DATE = BKG_CHNL_MSR.BOOKINGS_PROCESS_DATE
      AND BKGS.BKGS_MEASURE_TRANS_TYPE_CODE = BKG_CHNL_MSR.BKGS_MEASURE_TRANS_TYPE_CODE
   INNER JOIN
      {{ var('m_MT_RSTD_SA_BKGS_MONTH_COMREFVWDB') }}.R_FISCAL_DAY_TO_YEAR FD2Y
      ON BKGS.BOOKINGS_PROCESS_DATE = FD2Y.CALENDAR_DATE
      AND FD2Y.FISCAL_YEAR_AGE BETWEEN 0 AND 3
--AND FD2Y.FISCAL_YEAR_MONTH_INT=201411
/*INNER JOIN    SLSORDVWDB.N_SALES_ORDER_LINE_TV SOL
ON  SOL.SALES_ORDER_LINE_KEY=CASE WHEN BKGS_MSR.SALES_ORDER_LINE_KEY<=-1000000 THEN -9999 ELSE BKGS_MSR.SALES_ORDER_LINE_KEY END 
AND  SOL.END_TV_DATETIME = '3500-01-01 00:00:00'*/
WHERE
   COLLATE(BKGS.DV_REVENUE_RECOGNITION_FLG, 'en-ci-rtrim') = 'Y'
   AND COLLATE(BKGS.SERVICE_FLG, 'en-ci-rtrim') = 'N'
GROUP BY
   BKG_CHNL_MSR.DV_DRCT_VAL_ADDED_DSTI_ORD_FLG,
   BKG_CHNL_MSR.PARTNER_SITE_PARTY_KEY,
   CHANNEL_BOOKINGS_FLG,
   BKGS.PRODUCT_KEY,
   BKGS.SALES_TERRITORY_KEY,
   BKGS.SALES_REP_NUMBER,
   FD2Y.FISCAL_YEAR_MONTH_INT,
   BKGS.END_CUSTOMER_KEY,
   BKGS.BILL_TO_CUSTOMER_KEY,
   BKGS.SHIP_TO_CUSTOMER_KEY,
   BKGS.SOLD_TO_CUSTOMER_KEY,
   BKGS.BKGS_MEASURE_TRANS_TYPE_CODE,
   BKGS.SERVICE_FLG,
   BKGS.WIPS_ORIGINATOR_ID_INT,
   BKGS.CORPORATE_BOOKINGS_FLG,
   BKGS.DV_REVENUE_RECOGNITION_FLG,
   BKGS.DV_NET_SPREAD_FLG,
   BKGS.DV_ATTRIBUTION_CD,
   DV_PRODUCT_KEY,
   CANCEL_CODE,
   BKGS.DV_FMV_FLG,
   BKGS.ADJUSTMENT_CODE,
   BKGS.DSV_FLG /* Added as part of  Q1FY16 DSV **/,
   BKGS.XCAT_FLG,
   BKGS.BK_OFFER_TYPE_NAME,
   BKGS.RECURRING_OFFER_FLG,
   BKGS.ELA_FLG,
   BKGS.DV_RECURRING_OFFER_CD